source='''from collections import Counter, defaultdict

def transform(grid):
    height, width = len(grid), len(grid[0])
    output = [row[:] for row in grid]

    # Infer the repeating diagonal color cycle from the intact patterned area.
    counts = Counter(
        grid[r][c]
        for r in range(3, height)
        for c in range(3, width)
        if grid[r][c] != 0
    )
    palette = {color for color, count in counts.items() if count > 10}
    period = len(palette)
    bins = defaultdict(Counter)
    for r in range(3, height):
        for c in range(3, width):
            color = grid[r][c]
            if color in palette:
                bins[(r + c) % period][color] += 1
    by_phase = {phase: counter.most_common(1)[0][0] for phase, counter in bins.items()}

    for r in range(height):
        for c in range(width):
            if output[r][c] != 0:
                continue
            if r < 2 or c < 2:
                output[r][c] = 1
            elif r == 2 or c == 2:
                output[r][c] = 4
            else:
                output[r][c] = by_phase[(r + c) % period]
    return output
'''
